import numpy as np, pandas as pd
from darts import TimeSeries
from darts.models import NaiveSeasonal
from darts.metrics import err, mae, mse
s = TimeSeries.from_values(np.arange(1.,11.).reshape(-1,1), columns=['x'])
m=NaiveSeasonal(K=1)
for kwargs in [dict(), dict(start=5), dict(start=5,start_format='position'), dict(last_points_only=False), dict(forecast_horizon=2), dict(stride=2), dict(retrain=False), dict(train_length=3), dict(start=0.5)]:
    try:
        r=m.residuals(s, **kwargs)
        if isinstance(r,list):
            print(kwargs, 'list', len(r), [(x.time_index.tolist(), x.values().ravel().tolist()) for x in r[:2]])
        else:
            print(kwargs, type(r).__name__, r.time_index.tolist(), r.values().ravel().tolist(), r.components)
    except Exception as e:
        print(kwargs, 'ERR',type(e).__name__,e)
PY"}

