{"command": "cd /testbed && python - <<'PY'
import numpy as np
from darts import TimeSeries
from darts.models import NaiveSeasonal
from darts import metrics
m=NaiveSeasonal(K=1)
series=[TimeSeries.from_values(np.arange(1.,n+1.).reshape(-1,1), columns=['x']) for n in (6,8)]
# multi, lpo false
for lpo in [True,False]:
 print('lpo',lpo)
 r=m.residuals(series,last_points_only=lpo)
 print(type(r),len(r), [type(x).__name__ for x in r])
 for x in r:
  if isinstance(x,list): print('inner',len(x),[(e.time_index.tolist(), e.values().ravel().tolist()) for e in x[:2]])
  else: print('ts',x.time_index.tolist(),x.values().ravel().tolist())
# provided
s=series[0]
for lpo in [True,False]:
 hf=m.historical_forecasts(series=s,last_points_only=lpo)
 print('hf',lpo,type(hf), [type(x).__name__ for x in hf] if isinstance(hf,list) else hf)
 r=m.residuals(series=s,historical_forecasts=hf,last_points_only=lpo)
 if isinstance(r,list): print('res list', len(r), [x.time_index.tolist() if isinstance(x,TimeSeries) else len(x) for x in r])
 else: print('res ts',r.time_index.tolist(),r.values().ravel().tolist())
# multi provided
hf=m.historical_forecasts(series=series,last_points_only=True)
r=m.residuals(series=series,historical_forecasts=hf,last_points_only=True)
print('multi provided', type(r), len(r), [x.time_index.tolist() for x in r])
# wrong lpo
try: m.residuals(series=s,historical_forecasts=hf,last_points_only=False)
except Exception as e: print('wrong type',type(e).__name__,e)
PY"}

