import numpy as np
from darts import TimeSeries
from darts.models import LinearRegressionModel
from darts import metrics
s=TimeSeries.from_values(np.arange(1.,11.).reshape(-1,1), columns=['x'])
# deterministic LRM
for model in [LinearRegressionModel(lags=1), LinearRegressionModel(lags=1, likelihood='quantile', quantiles=[.1,.5,.9])]:
 print('model',model)
 for metric,mk in [(metrics.err,{}),(metrics.err,{'q':.5}),(metrics.err,{'q':[.1,.9]}),(metrics.iw,{'q_interval':(.1,.9)}),(metrics.iw,{'q_interval':[(.1,.9),(.2,.8)]})]:
  try:
   r=model.residuals(s,metric=metric,metric_kwargs=mk,random_state=42)
   print(metric.__name__,mk,type(r).__name__, list(r.components), r.values().shape, r.time_index.tolist())
   print(r.values().ravel().round(4).tolist())
  except Exception as e: print('ERR',metric.__name__,mk,type(e).__name__,e)
PY"}

